  final p149 = Path()..addRect(Rect.fromLTWH(24, 290, 252, 86));
  canvas.drawPath(
    p149,
    Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.2
      ..strokeCap = StrokeCap.butt
      ..strokeJoin = StrokeJoin.miter
      ..shader = LinearGradient(
        begin: Alignment(-1, -1),
        end: Alignment(1, 1),
        colors: [
          Color(0xFFC9B8FF),
          Color(0xFFA9E8F0),
          Color(0xFFF6C3DF),
          Color(0xFFD9F2E4),
          Color(0xFFB6C7FF),
          Color(0xFFF3D2F0),
        ],
        stops: [0, 0.22, 0.42, 0.6, 0.8, 1],
      ).createShader(p149.getBounds()),
  );
  final p150 = Path()
    ..moveTo(92, 352)
    ..lineTo(208, 352);
  canvas.drawPath(p150, Paint()..color = const Color(0xFF000000));
  canvas.drawPath(
    p150,
    Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.6
      ..strokeCap = StrokeCap.butt
      ..strokeJoin = StrokeJoin.miter
      ..shader = LinearGradient(
        begin: Alignment(-1, -1),
        end: Alignment(1, 1),
        colors: [
          Color(0xFFC9B8FF),
          Color(0xFFA9E8F0),
          Color(0xFFF6C3DF),
          Color(0xFFD9F2E4),
          Color(0xFFB6C7FF),
          Color(0xFFF3D2F0),
        ],
        stops: [0, 0.22, 0.42, 0.6, 0.8, 1],
      ).createShader(p150.getBounds()),
  );
}

/// SVG `stroke-dasharray`를 경로 길이를 따라 잘라 그립니다.
Path _dashed(Path source, List<double> pattern) {
  final out = Path();
  for (final metric in source.computeMetrics()) {
    var distance = 0.0;
    var index = 0;
    while (distance < metric.length) {
      final length = pattern[index % pattern.length];
      if (index.isEven) {
        out.addPath(
          metric.extractPath(distance, distance + length),
          Offset.zero,
        );
      }
      distance += length;
      index++;
    }
  }
  return out;
}
